description:
Manage heap arrays yourself with `new[]` and `delete[]`, the way `std::vector` does inside:

```cpp
int* makeArray(int count, int fill);
void freeArray(int*& array);
int* grow(int* old, int oldCount, int newCount, int fill);
char* duplicate(const char* text);
```

- **makeArray** allocates `count` ints with `new[]`, all set to `fill`. A count of 0 or less returns `nullptr`.
- **freeArray** frees the array with `delete[]` and sets the caller's pointer to `nullptr`, so a second call is harmless.
- **grow** allocates a new array of `newCount` ints, copies over the first `min(oldCount, newCount)` values, sets any extra elements to `fill`, frees the old array and returns the new one. `old` may be `nullptr` (with `oldCount` 0).
- **duplicate** returns a heap copy of a C string, zero included, made with `new char[]`. The caller frees it with `delete[]`.

The tests count allocations to make sure nothing leaks and nothing is freed twice.

starter.solution.cpp:
int* makeArray(int count, int fill) { return nullptr; }
void freeArray(int*& array) {}
int* grow(int* old, int oldCount, int newCount, int fill) { return old; }
char* duplicate(const char* text) { return nullptr; }

solution.solution.cpp:
#include <cstring>

int* makeArray(int count, int fill)
{
    if (count <= 0) return nullptr;
    int* array{ new int[count] };
    for (int i{ 0 }; i < count; ++i) array[i] = fill;
    return array;
}

void freeArray(int*& array)
{
    delete[] array;
    array = nullptr;
}

int* grow(int* old, int oldCount, int newCount, int fill)
{
    int* fresh{ makeArray(newCount, fill) };
    const int keep{ oldCount < newCount ? oldCount : newCount };
    for (int i{ 0 }; i < keep; ++i) fresh[i] = old[i];
    delete[] old;
    return fresh;
}

char* duplicate(const char* text)
{
    const std::size_t length{ std::strlen(text) };
    char* copy{ new char[length + 1] };
    std::memcpy(copy, text, length + 1);
    return copy;
}

unitTests:
#include <cstdlib>
#include <new>
#include <string>
// Counts array allocations and frees made through new[] and delete[].
static int liveArrays{ 0 };
void* operator new[](std::size_t size) { ++liveArrays; if (void* p{ std::malloc(size ? size : 1) }) return p; throw std::bad_alloc{}; }
void operator delete[](void* p) noexcept { if (p) { --liveArrays; std::free(p); } }
void operator delete[](void* p, std::size_t) noexcept { if (p) { --liveArrays; std::free(p); } }

TEST("make and free") {
    const int before{ liveArrays };
    int* a{ makeArray(5, 7) };
    CHECK(a != nullptr);
    CHECK_EQ(liveArrays, before + 1);
    CHECK_EQ(a[0], 7); CHECK_EQ(a[4], 7);
    freeArray(a);
    CHECK(a == nullptr);
    CHECK_EQ(liveArrays, before);
    freeArray(a);
    CHECK_EQ(liveArrays, before);
    CHECK(makeArray(0, 1) == nullptr);
    CHECK_EQ(liveArrays, before);
}
TEST("grow keeps the old values") {
    const int before{ liveArrays };
    int* a{ makeArray(3, 1) };
    a[1] = 2; a[2] = 3;
    a = grow(a, 3, 6, 0);
    CHECK_EQ(liveArrays, before + 1);
    CHECK_EQ(a[0], 1); CHECK_EQ(a[1], 2); CHECK_EQ(a[2], 3); CHECK_EQ(a[3], 0); CHECK_EQ(a[5], 0);
    a = grow(a, 6, 2, 9);
    CHECK_EQ(a[0], 1); CHECK_EQ(a[1], 2);
    CHECK_EQ(liveArrays, before + 1);
    freeArray(a);
    int* b{ grow(nullptr, 0, 4, 8) };
    CHECK_EQ(b[3], 8);
    freeArray(b);
    CHECK_EQ(liveArrays, before);
}
TEST("duplicate") {
    const int before{ liveArrays };
    char* copy{ duplicate("heap") };
    CHECK_EQ(std::string(copy), std::string("heap"));
    CHECK_EQ(copy[4], '\0');
    copy[0] = 'H';
    CHECK_EQ(std::string(copy), std::string("Heap"));
    delete[] copy;
    char* empty{ duplicate("") };
    CHECK_EQ(empty[0], '\0');
    delete[] empty;
    CHECK_EQ(liveArrays, before);
}

